const StyledSidebar = styled.div`
    ${tw`bg-whiteStandard`};
    z-index: ${props => props.order + 30};

    position: fixed;
    transition: 0.3s ease-in-out;

    top: 0;

    height: 100%;
    width: 100vw;

    overflow-y: auto;

    right: ${props => (props.isOpen ? css`0` : '-100vw')};

    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;

    @media (min-width: 1024px) {
        width: ${props => (props.customWidth ? `${props.customWidth}px` : '480px')};

        right: ${props => (props.isOpen ? (props.order === 0 ? css`0` : '480px') : '-480px')};
        box-shadow: 0px 0px 4px 2px rgba(0, 0, 0, 0.05);

        z-index: ${props => (props.order === 1 ? 28 : props.order + 30)};
    }
`;

const ContentContainer = styled.div`
    position: relative;
    padding-top: 40px;
    padding-bottom: 40px;

    width: 100%;
    height: 100%;

    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
`;

const StyledHeading = styled.h1`
    text-align: center;

    font-size: 40px;
    font-weight: bold;
    ${tw`text-primary-dark`}
    line-height: 48px;

    margin-top: 32px;
    margin-bottom: 24px;

    white-space: pre-line;

    @media (max-width: 768px) {
        font-size: 36px;
    }
`;

const ShareLinkDiv = styled.div`
    width: 100%;

    padding-left: 40px;
    padding-right: 40px;
`;

